#include <bits/stdc++.h>
using namespace std;

int main() {
	
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    int N=3*n;
	    vector<long long> a(N);
	    for(int i=0;i<N;i++){
	        cin>>a[i];
	    }
	        sort(a.rbegin(),a.rend());
	        vector<long long>pre(N+1, 0);
	        for(int i=0;i<N;i++)
	           pre[i+1]=pre[i]+a[i];
	           
	        
	    
	        long long ans=0;
	        for(int p=0;p<=n;p++){
	            int lo=0;
	            int hi=p;
	            while(lo<hi){
	                int mid=lo+(hi-lo)/2;
	                long long diff=2LL*a[mid]-a[2*p-mid-1]-3LL*a[3*n-p-mid-1];
	                if(diff>=0)
	                     lo=mid+1;
	               else
	                    hi=mid;   
	            }
	            for(int c1: {lo, lo-1}){
	                if(c1<0 || c1>p)
	                    continue;
	               int q=2*p-c1;
	               int m=3*n-p-c1;
	               long long cur=2LL*pre[c1]+pre[q]+3LL*pre[m];
	               ans=max(ans,cur);
	            }
	            
	            
	        }
	        cout<<ans<<endl;
	        
	    
	    
	}

}
